const {chromium}=require('/Users/evanrobinson/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
(async()=>{const browser=await chromium.launch({channel:'chrome',headless:true});try{const page=await browser.newPage({viewport:{width:1280,height:720}});await page.route('**/lab.mjs*',async route=>{const response=await route.fetch();await route.fulfill({response,body:(await response.text())+'\nglobalThis.__physicsTest={active:()=>active,pause:()=>running=false};'});});await page.route('**/ranch-motion-ui.mjs*',async route=>{const r=await route.fetch();await route.fulfill({response:r,body:(await r.text()).replace('settled:b.settled,','settled:b.settled,rotation:b.rotation,restRotation:b.restRotation,righting:b.righting,contact:b.contact,angularVelocity:b.angularVelocity,recoveryState:b.recovery,')});});await page.goto('http://127.0.0.1:8841/');await page.waitForFunction(()=>globalThis.__physicsTest?.active()?.life,null,{timeout:90000});await page.waitForTimeout(3000);await page.evaluate(()=>__physicsTest.pause());await page.locator('#advanced-open').click();await page.locator('[data-action=lift]').click();await page.waitForTimeout(1800);await page.locator('[data-action=tilt]').click();await page.waitForTimeout(1500);await page.locator('[data-action=return]').click();await page.waitForTimeout(5000);console.log(JSON.stringify(await page.evaluate(()=>{const a=__physicsTest.active(),held=JSON.parse(document.querySelector('.tile-motion-controls').dataset.physics);return {held,entities:a.life.physics.entities().filter(e=>held.some(h=>h.id===e.bodyId)).map(e=>({id:e.bodyId,position:e.position,local:e.body.position.toArray(),parent:e.body.parent.position.toArray(),radius:e.radius,recovery:e.recovery}))};})));}finally{await browser.close();}})().catch(e=>{console.error(e);process.exit(1)});
